<body>

    <header>
        <h1>Autonomous Multi-Bot Maze Exploration</h1>
        <p>24 bots independently discover the exit of a perfect maze using Trémaux/DFS logic without global layout awareness.</p>
    </header>

    <div class="container">
        <!-- Left Column: The Maze Canvas -->
        <div class="maze-panel">
            <div id="maze">
                <canvas id="mazeCanvas" width="600" height="600"></canvas>
            </div>
        </div>

        <!-- Right Column: Controls, Stats & Bots -->
        <div class="dashboard">
            <!-- Stats -->
            <div class="card stats-grid">
                <div class="stat-box">
                    <div class="stat-label">Bots Completed</div>
                    <div class="stat-value completed" id="completed">0</div>
                </div>
                <div class="stat-box">
                    <div class="stat-label">Ticks Elapsed</div>
                    <div class="stat-value timer" id="timer">0</div>
                </div>
            </div>

            <!-- Simulation Controls -->
            <div class="card controls">
                <div class="btn-group">
                    <button id="playPauseBtn" class="primary">Pause</button>
                    <button id="stepBtn" class="secondary">Step (+1 Tick)</button>
                </div>
                <div class="btn-group">
                    <button id="tick100Btn" class="secondary">Fast Forward (+100)</button>
                    <button id="reset" class="danger">New Maze</button>
                </div>

                <div class="slider-container">
                    <div class="slider-header">
                        <span>Simulation Speed</span>
                        <span id="speedVal">10 ticks/sec</span>
                    </div>
                    <input type="range" id="speedSlider" min="1" max="200" value="10">
                </div>

                <div style="border-top: 1px solid var(--border-color); margin-top: 0.5rem; padding-top: 0.75rem;">
                    <div class="slider-header">
                        <span>Seed Controls</span>
                        <span id="displaySeed" style="font-family: monospace; color: var(--accent);"></span>
                    </div>
                    <div class="seed-input-container">
                        <input type="text" id="seedInput" placeholder="Enter custom seed">
                        <button id="applySeedBtn" class="secondary" style="padding: 0.4rem 0.75rem; font-size: 0.8rem;">Apply</button>
                    </div>
                </div>
            </div>

            <!-- Bot Tracker Grid -->
            <div class="card">
                <div class="bot-list-title">Explorers (24 Bots)</div>
                <div class="bots-grid" id="botsGrid"></div>
            </div>
        </div>
    </div>

    <script>
        // Permutations Generator for Direction preferences
        const dirs = ['n', 'e', 's', 'w'];
        const permutations = [];
        function permute(arr, m = []) {
            if (arr.length === 0) {
                permutations.push(m);
            } else {
                for (let i = 0; i < arr.length; i++) {
                    let curr = arr.slice();
                    let next = curr.splice(i, 1);
                    permute(curr, m.concat(next));
                }
            }
        }
        permute(dirs); // Produces exactly 24 unique permuted preferences

        // Custom PRNG: Mulberry32
        function createRandom(seed) {
            let state = seed;
            return function() {
                let t = state += 0x6D2B79F5;
                t = Math.imul(t ^ (t >>> 15), t | 1);
                t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
                return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
            }
        }

        // Maze Generator (Seeded Recursive Backtracker DFS)
        function generateMaze(rows, cols, prng) {
            const grid = [];
            for (let r = 0; r < rows; r++) {
                const row = [];
                for (let c = 0; c < cols; c++) {
                    row.push({ n: true, e: true, s: true, w: true });
                }
                grid.push(row);
            }

            const visited = Array.from({ length: rows }, () => Array(cols).fill(false));
            const stack = [];
            let current = { r: 0, c: 0 };
            visited[0][0] = true;
            let visitedCount = 1;
            const totalCells = rows * cols;

            while (visitedCount < totalCells) {
                const neighbors = [];
                const r = current.r;
                const c = current.c;

                if (r > 0 && !visited[r - 1][c]) neighbors.push({ r: r - 1, c: c, dir: 'n', opp: 's' });
                if (r < rows - 1 && !visited[r + 1][c]) neighbors.push({ r: r + 1, c: c, dir: 's', opp: 'n' });
                if (c > 0 && !visited[r][c - 1]) neighbors.push({ r: r, c: c - 1, dir: 'w', opp: 'e' });
                if (c < cols - 1 && !visited[r][c + 1]) neighbors.push({ r: r, c: c + 1, dir: 'e', opp: 'w' });

                if (neighbors.length > 0) {
                    const index = Math.floor(prng() * neighbors.length);
                    const next = neighbors[index];

                    grid[current.r][current.c][next.dir] = false;
                    grid[next.r][next.c][next.opp] = false;

                    stack.push(current);
                    current = { r: next.r, c: next.c };
                    visited[current.r][current.c] = true;
                    visitedCount++;
                } else if (stack.length > 0) {
                    current = stack.pop();
                } else {
                    break;
                }
            }
            return grid;
        }

        // Single simulation step of a bot
        function stepBot(bot) {
            if (bot.finishTick !== null) {
                return;
            }

            const r = bot.r;
            const c = bot.c;
            const cellWalls = window.game.walls(r, c);

            let nextMove = null;

            // Try to move to an unvisited neighbor based on preferred direction order
            for (let dir of bot.pref) {
                if (!cellWalls[dir]) {
                    let nr = r, nc = c;
                    if (dir === 'n') nr--;
                    else if (dir === 's') nr++;
                    else if (dir === 'e') nc++;
                    else if (dir === 'w') nc--;

                    const neighborKey = `${nr},${nc}`;
                    if (!bot.visited.has(neighborKey)) {
                        nextMove = { r: nr, c: nc };
                        break;
                    }
                }
            }

            if (nextMove) {
                // Move forward
                bot.r = nextMove.r;
                bot.c = nextMove.c;
                bot.visited.add(`${bot.r},${bot.c}`);
                bot.stack.push({ r: bot.r, c: bot.c });
                bot.path.push({ r: bot.r, c: bot.c });
            } else {
                // No unvisited neighbors. Backtrack!
                // First, mark current cell as a dead end
                const currentCellKey = `${bot.r},${bot.c}`;
                if (!bot.deadEnds.some(cell => cell.r === bot.r && cell.c === bot.c)) {
                    bot.deadEnds.push({ r: bot.r, c: bot.c });
                }

                if (bot.stack.length > 1) {
                    bot.stack.pop(); // Pop current cell
                    const prev = bot.stack[bot.stack.length - 1]; // Previous cell
                    bot.r = prev.r;
                    bot.c = prev.c;
                    bot.path.push({ r: bot.r, c: bot.c });
                }
            }

            // Check if we arrived at the exit
            if (bot.r === window.game.exit.r && bot.c === window.game.exit.c) {
                bot.finishTick = window.game.elapsed;
            }
        }

        // Main game state & configuration
        window.game = {
            size: { rows: 15, cols: 15 },
            spawn: { r: 0, c: 0 },
            exit: { r: 14, c: 14 },
            elapsed: 0,
            bots: [],
            currentSeed: null,
            _grid: null,

            walls: function(r, c) {
                if (r < 0 || r >= this.size.rows || c < 0 || c >= this.size.cols) {
                    return { n: true, e: true, s: true, w: true };
                }
                return this._grid[r][c];
            },

            tick: function(n) {
                for (let i = 0; i < n; i++) {
                    if (allBotsFinished()) {
                        break;
                    }
                    this.elapsed++;
                    for (let bot of this.bots) {
                        stepBot(bot);
                    }
                }
                visualTime = this.elapsed;
                syncUI();
            },

            reset: function(seed) {
                // Seed determination
                let numericSeed;
                if (typeof seed === 'number') {
                    numericSeed = seed;
                } else if (typeof seed === 'string' && !isNaN(Number(seed)) && seed.trim() !== '') {
                    numericSeed = Number(seed);
                } else {
                    numericSeed = Math.floor(Math.random() * 2000000000);
                }

                this.currentSeed = numericSeed;
                const prng = createRandom(numericSeed);

                // Generate deterministic maze
                this._grid = generateMaze(this.size.rows, this.size.cols, prng);

                // Seeded shuffle of direction permutations to assign to bots
                const botPerms = JSON.parse(JSON.stringify(permutations));
                for (let i = botPerms.length - 1; i > 0; i--) {
                    const j = Math.floor(prng() * (i + 1));
                    const temp = botPerms[i];
                    botPerms[i] = botPerms[j];
                    botPerms[j] = temp;
                }

                // Initialize 24 bots
                this.bots = [];
                for (let i = 0; i < 24; i++) {
                    const bot = {
                        path: [{ r: this.spawn.r, c: this.spawn.c }],
                        deadEnds: [],
                        finishTick: null,
                        // Internal DFS tracking
                        r: this.spawn.r,
                        c: this.spawn.c,
                        visited: new Set([`${this.spawn.r},${this.spawn.c}`]),
                        stack: [{ r: this.spawn.r, c: this.spawn.c }],
                        pref: botPerms[i],
                        color: `hsl(${(i * 360 / 24)}, 90%, 55%)`
                    };

                    // Guard if spawn is also exit
                    if (bot.r === this.exit.r && bot.c === this.exit.c) {
                        bot.finishTick = 0;
                    }

                    this.bots.push(bot);
                }

                // Reset visual animation clock
                visualTime = 0;
                this.elapsed = 0;

                // Sync controls and rebuild badges
                document.getElementById('seedInput').value = this.currentSeed;
                document.getElementById('displaySeed').textContent = this.currentSeed;
                rebuildBotGrid();
                syncUI();
            }
        };

        // Utility to check if all bots completed exploration
        function allBotsFinished() {
            return window.game.bots.every(bot => bot.finishTick !== null);
        }

        // Global UI & Rendering fields
        const canvas = document.getElementById('mazeCanvas');
        const ctx = canvas.getContext('2d');
        const completedEl = document.getElementById('completed');
        const timerEl = document.getElementById('timer');
        const playPauseBtn = document.getElementById('playPauseBtn');
        const speedSlider = document.getElementById('speedSlider');
        const speedVal = document.getElementById('speedVal');

        let isPaused = false;
        let speed = 10; // Ticks per second
        let visualTime = 0; // Float for sub-tick smooth interpolation
        let lastFrameTime = 0;

        // Rebuild badge DOM grid
        function rebuildBotGrid() {
            const grid = document.getElementById('botsGrid');
            grid.innerHTML = '';
            window.game.bots.forEach((bot, i) => {
                const badge = document.createElement('div');
                badge.className = 'bot-badge';
                badge.id = `badge-${i}`;
                badge.style.backgroundColor = bot.color;
                badge.style.setProperty('--badge-color', bot.color);

                const label = document.createElement('div');
                label.textContent = `B${i+1}`;
                badge.appendChild(label);

                const info = document.createElement('div');
                info.className = 'tick-info';
                info.id = `badge-info-${i}`;
                info.textContent = 'Active';
                badge.appendChild(info);

                grid.appendChild(badge);
            });
        }

        // Quick UI Sync for non-render elements
        function syncUI() {
            const finishedCount = window.game.bots.filter(bot => bot.finishTick !== null).length;
            completedEl.textContent = `${finishedCount} / 24`;
            timerEl.textContent = window.game.elapsed;

            // Sync badges
            window.game.bots.forEach((bot, i) => {
                const badge = document.getElementById(`badge-${i}`);
                const info = document.getElementById(`badge-info-${i}`);
                if (badge && info) {
                    if (bot.finishTick !== null) {
                        badge.className = 'bot-badge finished';
                        info.textContent = `T${bot.finishTick}`;
                    } else {
                        badge.className = 'bot-badge active';
                        info.textContent = 'Active';
                    }
                }
            });

            // Pause Button text
            if (allBotsFinished()) {
                playPauseBtn.textContent = 'Completed';
                playPauseBtn.disabled = true;
            } else {
                playPauseBtn.disabled = false;
                playPauseBtn.textContent = isPaused ? 'Play' : 'Pause';
            }
        }

        // Draw and animate maze framework
        function render() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            const rows = window.game.size.rows;
            const cols = window.game.size.cols;
            const cellSize = canvas.width / cols;

            // 1. Draw Passage Floor
            ctx.fillStyle = '#1e293b';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // 2. Draw Spawn and Exit Cells
            // Spawn (0,0)
            ctx.fillStyle = 'rgba(16, 185, 129, 0.25)';
            ctx.fillRect(0, 0, cellSize, cellSize);
            // Exit (14,14)
            ctx.fillStyle = 'rgba(239, 68, 68, 0.25)';
            ctx.fillRect((cols-1)*cellSize, (rows-1)*cellSize, cellSize, cellSize);

            // 3. Draw Dead Ends (Subtle dots of each bot's color)
            window.game.bots.forEach((bot) => {
                ctx.fillStyle = bot.color;
                ctx.globalAlpha = 0.15;
                for (let dead of bot.deadEnds) {
                    const cx = dead.c * cellSize + cellSize / 2;
                    const cy = dead.r * cellSize + cellSize / 2;
                    ctx.beginPath();
                    ctx.arc(cx, cy, 3, 0, 2 * Math.PI);
                    ctx.fill();
                }
            });
            ctx.globalAlpha = 1.0;

            // 4. Draw Walls
            ctx.strokeStyle = '#475569';
            ctx.lineWidth = 3.5;
            ctx.lineCap = 'round';

            for (let r = 0; r < rows; r++) {
                for (let c = 0; c < cols; c++) {
                    const walls = window.game.walls(r, c);
                    const x = c * cellSize;
                    const y = r * cellSize;

                    if (walls.n) {
                        ctx.beginPath();
                        ctx.moveTo(x, y);
                        ctx.lineTo(x + cellSize, y);
                        ctx.stroke();
                    }
                    if (walls.s) {
                        ctx.beginPath();
                        ctx.moveTo(x, y + cellSize);
                        ctx.lineTo(x + cellSize, y + cellSize);
                        ctx.stroke();
                    }
                    if (walls.w) {
                        ctx.beginPath();
                        ctx.moveTo(x, y);
                        ctx.lineTo(x, y + cellSize);
                        ctx.stroke();
                    }
                    if (walls.e) {
                        ctx.beginPath();
                        ctx.moveTo(x + cellSize, y);
                        ctx.lineTo(x + cellSize, y + cellSize);
                        ctx.stroke();
                    }
                }
            }

            // Labels for Start & Exit
            ctx.fillStyle = '#34d399';
            ctx.font = 'bold 12px sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('START', cellSize/2, cellSize/2);

            ctx.fillStyle = '#f87171';
            ctx.fillText('EXIT', (cols-0.5)*cellSize, (rows-0.5)*cellSize);

            // 5. Draw Bots with smooth visual transitions
            window.game.bots.forEach((bot, botIndex) => {
                // Determine previous and next visual steps based on floating visualTime
                let t1 = Math.floor(visualTime);
                let t2 = t1 + 1;
                let f = visualTime - t1;

                let p1, p2;

                // Get coordinates at time t1
                if (t1 >= bot.path.length) {
                    p1 = bot.path[bot.path.length - 1];
                } else {
                    p1 = bot.path[t1];
                }

                // Get coordinates at time t2
                if (t2 >= bot.path.length) {
                    p2 = p1;
                } else {
                    p2 = bot.path[t2];
                }

                // Linear interpolation
                const interpR = p1.r + (p2.r - p1.r) * f;
                const interpC = p1.c + (p2.c - p1.c) * f;

                // Calculate visual position centered in corridors
                // Apply a small offset unique to each bot to prevent perfectly overlapping dots
                const angle = (botIndex * (2 * Math.PI / 24));
                const radiusOffset = 7;
                const offsetX = Math.cos(angle) * radiusOffset;
                const offsetY = Math.sin(angle) * radiusOffset;

                const bx = interpC * cellSize + cellSize / 2 + offsetX;
                const by = interpR * cellSize + cellSize / 2 + offsetY;

                // Draw bot circle
                ctx.beginPath();
                ctx.arc(bx, by, 6.5, 0, 2 * Math.PI);
                ctx.fillStyle = bot.color;
                ctx.fill();
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 1.5;
                ctx.stroke();

                // Small center iris
                ctx.beginPath();
                ctx.arc(bx, by, 2, 0, 2 * Math.PI);
                ctx.fillStyle = '#000000';
                ctx.fill();
            });
        }

        // Smooth Animation Frame Loop
        function animateLoop(timestamp) {
            if (!lastFrameTime) lastFrameTime = timestamp;
            let dt = (timestamp - lastFrameTime) / 1000;
            if (dt > 0.1) dt = 0.1; // Cap to avoid massive skips
            lastFrameTime = timestamp;

            if (!isPaused) {
                if (allBotsFinished()) {
                    visualTime = window.game.elapsed;
                    syncUI();
                } else {
                    // Step simulation forward as visual pointer catches up
                    if (visualTime >= window.game.elapsed) {
                        window.game.tick(1);
                    }
                    visualTime += dt * speed;
                    if (visualTime > window.game.elapsed) {
                        visualTime = window.game.elapsed;
                    }
                }
            }

            render();
            requestAnimationFrame(animateLoop);
        }

        // Action and event bindings
        playPauseBtn.addEventListener('click', () => {
            if (allBotsFinished()) return;
            isPaused = !isPaused;
            syncUI();
        });

        document.getElementById('stepBtn').addEventListener('click', () => {
            isPaused = true;
            window.game.tick(1);
            syncUI();
        });

        document.getElementById('tick100Btn').addEventListener('click', () => {
            isPaused = true;
            window.game.tick(100);
            syncUI();
        });

        document.getElementById('reset').addEventListener('click', () => {
            window.game.reset(); // new random seed
        });

        document.getElementById('applySeedBtn').addEventListener('click', () => {
            const seedVal = document.getElementById('seedInput').value;
            window.game.reset(seedVal);
        });

        speedSlider.addEventListener('input', (e) => {
            speed = parseInt(e.target.value);
            speedVal.textContent = `${speed} ticks/sec`;
        });

        // Initialize App
        window.game.reset(12345); // Starter reproducible seed
        requestAnimationFrame(animateLoop);
    </script>
